const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={students:[{id:1,name:'Lucas Costa',goal:'Hipertrofia',level:'Intermediário'},{id:2,name:'Marina Santos',goal:'Condicionamento',level:'Iniciante'},{id:3,name:'Pedro Almeida',goal:'Força',level:'Avançado'}],plans:{1:[{name:'Supino reto',sets:4,reps:12,weight:30,rest:60},{name:'Supino inclinado',sets:3,reps:12,weight:22,rest:60},{name:'Crucifixo com halteres',sets:3,reps:15,weight:10,rest:45},{name:'Tríceps na polia',sets:3,reps:12,weight:20,rest:45}],2:[],3:[]},logs:[],measurements:[],messages:[{role:'personal',text:'Olá, Lucas! Seu treino está atualizado. Registre as cargas e me conte como foi a sessão.'}]};
let data;try{data=JSON.parse(localStorage.getItem(window.hpeDataKey||'forja-v1'))||initial}catch{data=initial}let page='inicio',role='aluno',student=1,done=new Set();const save=()=>{localStorage.setItem(window.hpeDataKey||'forja-v1',JSON.stringify(data));window.hpeSyncChanged?.()};const current=()=>(data.students.find(s=>s.id===student)||{name:"Novo aluno",goal:"Cadastre seu primeiro aluno",level:""});function plan(){const block=window.currentTrainingBlock||"A";if(block==="A")return data.plans[student]??=[];data.alternatePlans??={};data.alternatePlans[student]??={};return data.alternatePlans[student][block]??=[]}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}function modal(html){$('#modalbody').innerHTML=html;$('#modal').showModal()}function go(p){page=p;render()}window.go=go;
$('#role').disabled=true;
const accounts={aluno:{email:'aluno@forja.demo',name:'Lucas Costa'},personal:{email:'personal@forja.demo',name:'Rafael Alves'}};
let loginRole='aluno';
const loginPanel=document.createElement('section');loginPanel.id='login';document.body.prepend(loginPanel);
const logoutButton=document.createElement('button');logoutButton.textContent='Sair';logoutButton.onclick=()=>{sessionStorage.removeItem('forja-session');done.clear();$('#modal').close();showLogin()};$('header>div').append(logoutButton);
function showLogin(selected=loginRole){loginRole=selected;document.body.classList.add('signed-out');loginPanel.innerHTML=`<div class="login-story"><a class="brand hpe-brand" href="#" aria-label="HPE Força Bruta"><img src="hpe-forca-bruta.png" alt="HPE Força Bruta" width="1536" height="1024"></a><span class="eyebrow">SEU PRÓXIMO NÍVEL</span><h1>O seu objetivo.<br>O nosso movimento.</h1><p>Treino personalizado, evolução acompanhada e uma conexão mais próxima com seu personal.</p><div class="login-benefits"><span>01 &nbsp; Treine com propósito</span><span>02 &nbsp; Acompanhe sua evolução</span><span>03 &nbsp; Evolua em parceria</span></div></div><div class="login-card card"><span class="eyebrow">BEM-VINDO À HPE FORÇA BRUTA</span><h2>Entre no seu espaço.</h2><p>Escolha seu perfil para continuar.</p><div class="login-tabs" role="tablist" aria-label="Perfil de acesso"><button role="tab" aria-selected="${selected==='aluno'}" class="${selected==='aluno'?'primary':''}" onclick="showLogin('aluno')">Sou aluno</button><button role="tab" aria-selected="${selected==='personal'}" class="${selected==='personal'?'primary':''}" onclick="showLogin('personal')">Sou personal</button></div><form id="loginForm"><label>E-mail<input type="email" name="email" autocomplete="username" placeholder="${accounts[selected].email}" required></label><label>Senha<div class="password-field"><input id="loginPassword" name="password" type="password" autocomplete="current-password" required><button type="button" id="showPassword" aria-label="Mostrar senha" aria-pressed="false">Mostrar</button></div></label><p id="loginError" role="alert" hidden></p><button class="primary">Entrar como ${selected==='aluno'?'aluno':'personal'} &nbsp; ↗</button></form><div class="demo-access"><b>Acesso de demonstração</b><p>E-mail: ${accounts[selected].email}<br>Senha: forja123</p><button type="button" id="fillDemo">Preencher acesso de teste</button></div><p class="note">Use apenas os dados de teste acima. Este login demonstra os perfis e não protege os dados locais como uma autenticação real.</p></div>`;
$('#showPassword').onclick=e=>{const visible=$('#loginPassword').type==='password';$('#loginPassword').type=visible?'text':'password';e.target.textContent=visible?'Ocultar':'Mostrar';e.target.setAttribute('aria-pressed',String(visible));e.target.setAttribute('aria-label',visible?'Ocultar senha':'Mostrar senha')};
$('#fillDemo').onclick=()=>{const f=$('#loginForm');f.elements.email.value=accounts[selected].email;f.elements.password.value='forja123';f.elements.email.focus()};
$('#loginForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('email').trim().toLowerCase()!==accounts[selected].email||f.get('password')!=='forja123'){$('#loginError').hidden=false;$('#loginError').textContent='E-mail ou senha inválidos para este perfil. Use o acesso de demonstração.';return}sessionStorage.setItem('forja-session',selected);enterApp(selected)};
}
window.showLogin=showLogin;
function enterApp(selected){role=selected;student=(visibleStudents()[0]?.id||0);page='inicio';done.clear();$('#role').value=role;$('header .avatar').textContent=role==='personal'?'RA':'LC';document.body.classList.remove('signed-out');loginPanel.innerHTML='';render();$('header button').focus()}
document.addEventListener('DOMContentLoaded',()=>{const session=sessionStorage.getItem('forja-session');if(accounts[session])enterApp(session);else showLogin()});
function chart(){const pts=data.measurements.filter(x=>x.student===student);if(!pts.length)return '<div class="empty">Sua evolução começa no primeiro registro.<br>Adicione peso e medidas na aba Evolução.</div>';const max=Math.max(...pts.map(x=>x.weight))+2,min=Math.min(...pts.map(x=>x.weight))-2;return `<svg class="chart" viewBox="0 0 400 170" role="img" aria-label="Evolução do peso"><path d="M10 140H390 M10 90H390 M10 40H390" stroke="#353e2e" fill="none"/><polyline points="${pts.map((x,i)=>`${20+i*360/Math.max(1,pts.length-1)},${140-(x.weight-min)/(max-min)*110}`).join(' ')}" stroke="#c4f36b" stroke-width="3" fill="none"/>${pts.map((x,i)=>`<circle cx="${20+i*360/Math.max(1,pts.length-1)}" cy="${140-(x.weight-min)/(max-min)*110}" r="5" fill="#c4f36b"/>`).join('')}</svg>`}
function heading(k,t,p,action=''){return `<div class="row"><div><span class="eyebrow">${k}</span><h1>${t}</h1><p>${p}</p></div>${action}</div>`}
function render(){const menus=role==='personal'?[['inicio','◫','Visão geral'],['alunos','♙','Meus alunos'],['treinos','▤','Criar treinos'],['evolucao','↗','Evolução'],['interacao','◌','Interação']]:[['inicio','◫','Visão geral'],['treinos','▤','Meu treino'],['evolucao','↗','Minha evolução'],['interacao','◌','Meu personal']];$('#nav').innerHTML=menus.map(([p,i,t])=>`<button class="${page===p?'active':''}" onclick="go('${p}')">${i} &nbsp; ${t}</button>`).join('');const selector=role==='personal'?`<select aria-label="Selecionar aluno" onchange="selectStudent(this.value)">${visibleStudents().map(s=>`<option value="${s.id}" ${s.id===student?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:'';const logs=data.logs.filter(l=>l.student===student);let h='';
if(page==='inicio'){h=heading('BEM-VINDO À HPE FORÇA BRUTA',role==='personal'?'Vamos construir evolução.':`Vamos pra cima, ${esc(current().name.split(' ')[0])}.`,role==='personal'?'Cada aluno tem um objetivo. Cada treino, um propósito.':'Sua melhor versão é construída com consistência.',selector)+`<div class="grid stats"><div class="card stat"><p>${role==='personal'?'Alunos acompanhados':'Treinos concluídos'}</p><strong>${role==='personal'?visibleStudents().length:logs.length}<span style="color:var(--green)"> ↗</span></strong><small>${role==='personal'?'Planos individuais':'Seu histórico real'}</small></div><div class="card stat"><p>Exercícios no plano</p><strong>${plan().length}</strong><small>${esc(current().goal)}</small></div><div class="card stat"><p>Registros de evolução</p><strong>${data.measurements.filter(m=>m.student===student).length}</strong><small>Acompanhe cada conquista</small></div></div><div class="two"><div><div class="hero"><span class="tag">SEU TREINO ATUAL</span><h2>Mais forte a cada repetição.</h2><p>Treino personalizado · ${esc(current().name)}<br>${plan().length} exercícios • ${esc(current().level)}</p><button class="primary" onclick="go('treinos')">${role==='personal'?'Gerenciar treino':'Começar meu treino'} &nbsp; ↗</button></div><h2>Consistência da semana</h2><div class="card week">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map((d,i)=>`<div class="day ${logs.some(l=>{let dt=new Date(l.date);let now=new Date();return dt.getDay()===i&&(now-dt)<604800000})?'done':''}">${d}<b>${['D','S','T','Q','Q','S','S'][i]}</b></div>`).join('')}</div></div><div class="card"><div class="row"><h3>Sua evolução</h3><span class="tag">PESO</span></div>${chart()}<p>Pequenos avanços. Grandes mudanças.</p><button onclick="go('evolucao')">Ver evolução &nbsp; ↗</button><div class="listrow"><span class="avatar">RA</span><div><b>Rafael Alves</b><p>Personal trainer • perfil de exemplo</p></div></div><button style="width:100%;margin-top:18px" onclick="go('interacao')">Conversar com o personal</button></div></div>`}
if(page==='alunos')h=heading('ÁREA DO PERSONAL','Cada pessoa. Um caminho.','Selecione um aluno para acompanhar seu plano.',`<button class="primary" onclick="addStudent()">+ Adicionar aluno</button>`)+`<div class="grid">${visibleStudents().map(s=>`<div class="card"><span class="avatar">${esc(s.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><h2>${esc(s.name)}</h2><span class="tag">${esc(s.goal)}</span><p>${esc(s.level)}<br>${(data.plans[s.id]||[]).length} exercícios no plano</p>${s.supabaseId?`<p class="student-access-code"><b>Código de acesso:</b> <code>${esc(s.accessCode||'—')}</code></p><button onclick="hpeConfirmStudentReset('${esc(s.supabaseId)}')">Redefinir senha</button>`:''}<button onclick="selectStudent(${s.id});go('treinos')">Abrir plano &nbsp; ↗</button></div>`).join('')}</div>`;
if(page==='treinos')h=heading('PLANO PERSONALIZADO',role==='personal'?'Um treino com propósito.':'Seu treino. Seu ritmo.',`${esc(current().name)} · ${esc(current().goal)} · ${esc(current().level)}`,selector)+`<div class="card"><div class="row"><div><h2>Treino de musculação</h2><p>${role==='personal'?'Ajuste séries, repetições e carga para este aluno.':'Veja a demonstração e marque cada exercício concluído.'}</p></div>${role==='personal'?'<button class="primary" onclick="editExercise()">+ Exercício</button>':`<span class="tag">${done.size} / ${plan().length} concluídos</span>`}</div>${plan().map((x,i)=>`<div class="exercise"><span class="num">${String(i+1).padStart(2,'0')}</span><div class="details"><b>${esc(x.name)}</b><p>${x.sets} séries × ${esc(x.reps)} repetições · ${x.weight} kg · ${x.rest}s descanso</p>${x.notes?`<p>${esc(x.notes)}</p>`:''}</div><button onclick="demo(${i})">▷ Ver movimento</button>${role==='personal'?`<button onclick="editExercise(${i})">Editar</button><button aria-label="Excluir ${esc(x.name)}" onclick="removeExercise(${i})">×</button>`:`<button class="${done.has(i)?'primary':''}" onclick="toggle(${i})" ${window.isWorkoutActive?.()?"":"disabled"}>${done.has(i)?'✓':'Concluir'}</button><button onclick="startRest(${i})" ${window.isWorkoutActive?.()?"":"disabled"}>◷ Descansar</button>`}</div>`).join('')||'<div class="empty">Ainda não há exercícios. O personal pode criar o plano.</div>'}${role==='aluno'?`<button class="primary" style="margin-top:24px" onclick="finish()" ${window.isWorkoutActive?.()&&done.size===plan().length&&plan().length?"":"disabled"}>✓ Treino concluído</button>`:''}<p class="note">Demonstrações esquemáticas animadas. O personal pode adicionar o link de um GIF específico em cada exercício.</p></div>`;
if(page==='evolucao')h=heading('ACOMPANHAMENTO','O resultado da constância.','Registre medidas e acompanhe seu desenvolvimento.',selector)+`<div class="two"><div class="card"><h2>Evolução do peso</h2>${chart()}<div class="listrow"><b>Data</b><b>Peso</b><b>Cintura</b></div>${data.measurements.filter(x=>x.student===student).slice().reverse().map(x=>`<div class="listrow"><div>${new Date(x.date).toLocaleDateString('pt-BR')}</div><div>${x.weight} kg</div><div>${x.waist?x.waist+' cm':'—'}</div></div>`).join('')}</div><div class="card"><h2>Registrar medidas</h2><form onsubmit="measurement(event)"><label>Peso (kg)<input name="weight" type="number" step="0.1" min="20" max="400" required></label><label>Cintura (cm) • opcional<input name="waist" type="number" step="0.1" min="20" max="300"></label><button class="primary">Salvar registro</button></form></div></div><h2>Histórico de treinos</h2><div class="card">${logs.slice().reverse().map(l=>`<div class="listrow"><span class="tag">✓ CONCLUÍDO</span><div><b>${new Date(l.date).toLocaleString('pt-BR')}</b><p>${l.count} exercícios · Esforço ${l.effort}/10 · ${esc(l.note||'Sem observações')}</p></div></div>`).join('')||'<p>Nenhum treino registrado ainda.</p>'}</div>`;
if(page==='interacao')h=heading('CONEXÃO QUE MOTIVA','Evoluímos juntos.','Um espaço para dúvidas, feedbacks e ajustes no treino.',selector)+`<div class="two"><div class="card"><div class="row"><div><h3>${role==='aluno'?'Rafael Alves · Personal':esc(current().name)}</h3><span class="muted">Conversa demonstrativa · salva neste navegador</span></div><span class="tag">FEEDBACK</span></div><div class="chat">${data.messages.filter(m=>!m.student||m.student===student).map(m=>`<div class="bubble ${m.role===role?'mine':''}"><small>${m.role==='personal'?'Personal':'Aluno'}</small>${esc(m.text)}</div>`).join('')}</div><form class="inline" onsubmit="message(event)"><input name="text" aria-label="Mensagem" placeholder="Escreva sua mensagem…" maxlength="2000" required><button class="primary">Enviar ↗</button></form></div><div class="card"><span class="eyebrow">SEU ACOMPANHAMENTO</span><h2>Converse. Ajuste. Evolua.</h2><p>Compartilhe como foi seu treino e tire dúvidas sobre o plano.</p><p>Saia da sua conta e entre no outro perfil para testar a resposta do personal.</p><span class="tag">${esc(current().goal)}</span><p class="note">Esta versão não envia mensagens para outras pessoas ou dispositivos.</p></div></div>`;$('#content').innerHTML=h}
window.selectStudent=id=>{student=Number(id);done.clear();render()};window.toggle=i=>{done.has(i)?done.delete(i):done.add(i);render()};window.removeExercise=i=>{plan().splice(i,1);save();render()};
window.editExercise=(i,preset)=>{const x=i===undefined?(preset||{name:'',sets:3,reps:12,weight:0,rest:60,gif:''}):plan()[i];modal(`<h2>${i===undefined?'Adicionar':'Editar'} exercício</h2><form id="exerciseForm"><label>Nome do exercício<input name="name" value="${esc(x.name)}" required maxlength="100"></label><div class="inline"><label>Séries<input name="sets" type="number" min="1" max="20" value="${x.sets}" required></label><label>Repetições<input name="reps" type="text" maxlength="150" value="${esc(x.reps)}" required></label></div><div class="inline"><label>Carga (kg)<input name="weight" type="number" min="0" max="1000" step="0.5" value="${x.weight}" required></label><label>Descanso (s)<input name="rest" type="number" min="0" max="600" value="${x.rest}" required></label></div><label>Orientação e método<textarea name="notes" maxlength="2000">${esc(x.notes||'')}</textarea></label><label>URL de demonstração GIF (opcional)<input name="gif" type="url" placeholder="https://…/exercicio.gif" value="${esc(x.gif||'')}"></label><button class="primary">Salvar exercício</button></form>`);$('#exerciseForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v={...x,name:f.get('name').trim(),sets:+f.get('sets'),reps:f.get('reps').trim(),weight:+f.get('weight'),rest:+f.get('rest'),gif:f.get('gif'),video:f.get('video')||'',muscle:x.muscle||'',notes:f.get('notes')||''};if(!v.name)return;if(v.gif&&!/^https:\/\//i.test(v.gif)){toast('Use um link HTTPS para o GIF.');return}const target=plan();if(i===undefined)target.push(v);else target[i]=v;save();$('#modal').close();render();toast('Treino atualizado para o aluno.') }};
window.demo=i=>{let x=plan()[i];modal(`<span class="eyebrow">DEMONSTRAÇÃO</span><h2>${esc(x.name)}</h2>${x.gif?`<img src="${esc(x.gif)}" alt="Demonstração de ${esc(x.name)}" style="width:100%;max-height:300px;object-fit:contain" onerror="this.outerHTML='<p>Não foi possível carregar o GIF. Peça ao personal para atualizar o link.</p>'">`:`<div class="demo"><svg viewBox="0 0 220 220" aria-label="Animação esquemática genérica"><path d="M30 180H190" stroke="#546442" stroke-width="4"/><circle cx="110" cy="45" r="17" fill="#c4f36b"/><path d="M110 65V125M110 125L80 180M110 125L140 180" fill="none" stroke="#c4f36b" stroke-width="12" stroke-linecap="round"/><g class="limb"><path d="M110 90L155 100L175 65" fill="none" stroke="#c4f36b" stroke-width="11" stroke-linecap="round"/><path d="M161 55L190 75" stroke="white" stroke-width="12"/></g></svg></div><p class="note">Animação ilustrativa genérica; não representa a técnica deste exercício. O personal pode cadastrar um GIF específico.</p>`}<p>${x.sets} séries × ${esc(x.reps)} repetições · ${x.rest}s de descanso</p>`)};
window.finish=()=>{if(!plan().length||done.size!==plan().length){toast('Conclua todos os exercícios antes de finalizar.');return}modal('<h2>Treino concluído. Boa!</h2><form id="finishForm"><label>Como foi o esforço? (1–10)<input name="effort" type="number" min="1" max="10" value="7" required></label><label>Feedback para o personal<textarea name="note" placeholder="Como você se sentiu?" maxlength="1000"></textarea></label><button class="primary">Registrar treino</button></form>');$('#finishForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);data.logs.push({student,date:new Date().toISOString(),count:done.size,effort:+f.get('effort'),note:f.get('note')});save();done.clear();$('#modal').close();go('evolucao');toast('Treino registrado!')}};
window.measurement=e=>{e.preventDefault();const f=new FormData(e.target);data.measurements.push({student,date:new Date().toISOString(),weight:+f.get('weight'),waist:+f.get('waist')});save();render();toast('Evolução registrada.')};window.message=e=>{e.preventDefault();const t=new FormData(e.target).get('text').trim();if(!t)return;data.messages.push({student,role,text:t});save();render();$('.chat').scrollTop=$('.chat').scrollHeight};
window.addStudent=()=>{modal('<h2>Novo aluno</h2><form id="studentForm"><label>Nome<input name="name" required maxlength="80"></label><label>Objetivo<select name="goal"><option>Hipertrofia</option><option>Condicionamento</option><option>Força</option></select></label><label>Nível<select name="level"><option>Iniciante</option><option>Intermediário</option><option>Avançado</option></select></label><button class="primary">Cadastrar aluno</button></form>');$('#studentForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;data.students.push({id:Date.now(),name,goal:f.get('goal'),level:f.get('level')});save();$('#modal').close();render();toast('Aluno cadastrado.')}};render();










